                if max(rs) >= er or max(cs) >= ec:
                    continue
            dist = min(abs(r-er)+abs(c-ec) for r,c in cells)
            item = (dist, other_color, cells, (min(rs),max(rs),min(cs),max(cs)))
            all_candidates.append(item)
            if min(cs) <= horiz_hi and max(cs) >= horiz_lo:
